extends Node2D

const SIZE := Vector2(640, 720)
const PLAYER_RADIUS := 18.0
var player := Vector2(320, 620)
var enemies: Array[Vector2] = []
var elapsed := 0.0
var spawn_left := 0.0
var running := false
var touch_x := -1.0
var rng := RandomNumberGenerator.new()
var hud := Label.new()
var button := Button.new()

func _ready() -> void:
	rng.randomize()
	hud.position = Vector2(24, 18)
	hud.add_theme_font_size_override("font_size", 24)
	add_child(hud)
	button.position = Vector2(210, 300)
	button.size = Vector2(220, 64)
	button.text = "开始 / 重新开始"
	button.pressed.connect(start_game)
	add_child(button)
	update_hud()
	queue_redraw()

func start_game() -> void:
	player = Vector2(320, 620)
	enemies.clear()
	elapsed = 0.0
	spawn_left = 0.4
	touch_x = -1.0
	running = true
	button.hide()
	update_hud()
	queue_redraw()

func _input(event: InputEvent) -> void:
	if event is InputEventScreenTouch:
		touch_x = event.position.x if event.pressed else -1.0
	elif event is InputEventScreenDrag:
		touch_x = event.position.x

func _process(delta: float) -> void:
	if not running:
		return
	# 暂时离开窗口后，不让一次大步进跳过碰撞。
	var dt := minf(delta, 0.05)
	elapsed += dt
	var axis := Input.get_axis("ui_left", "ui_right")
	if touch_x >= 0.0:
		player.x = move_toward(player.x, touch_x, 360.0 * dt)
	else:
		player.x += axis * 360.0 * dt
	player.x = clampf(player.x, PLAYER_RADIUS, SIZE.x - PLAYER_RADIUS)
	spawn_left -= dt
	if spawn_left <= 0.0:
		enemies.append(Vector2(rng.randf_range(20.0, 620.0), -20.0))
		spawn_left = maxf(0.18, 0.65 - elapsed * 0.006)
	for i in range(enemies.size() - 1, -1, -1):
		enemies[i].y += (200.0 + elapsed * 3.0) * dt
		if enemies[i].distance_to(player) < PLAYER_RADIUS + 15.0:
			running = false
			button.show()
			break
		if enemies[i].y > SIZE.y + 20.0:
			enemies.remove_at(i)
	update_hud()
	queue_redraw()

func update_hud() -> void:
	hud.text = "存活 %.1f 秒  |  方向键 / 触摸移动" % elapsed
	if not running and elapsed > 0.0:
		hud.text = "本局 %.1f 秒 · 碰到了！再试一次" % elapsed

func _draw() -> void:
	for x in range(0, 640, 40):
		draw_line(Vector2(x, 70), Vector2(x, 720), Color(0.10, 0.15, 0.22))
	draw_circle(player, PLAYER_RADIUS, Color(0.36, 0.94, 0.77))
	for enemy in enemies:
		draw_circle(enemy, 15.0, Color(1.0, 0.43, 0.39))

/* AI门道原创示例，MIT。Phaser 3.90.0 */
class CatchGame extends Phaser.Scene {
  constructor() { super('catch'); }
  create() {
    this.score = 0;
    this.remaining = 30;
    this.finished = false;
    this.spawnLeft = 0.6;
    this.coins = [];
    this.add.rectangle(240, 320, 480, 640, 0x102538);
    this.add.text(20, 18, 'CATCH THE GOLD', { fontSize: '22px', color: '#9befd7' });
    this.hud = this.add.text(20, 58, '', { fontSize: '22px' });
    this.player = this.add.rectangle(240, 580, 90, 20, 0x72ecc4);
    this.cursors = this.input.keyboard.createCursorKeys();
    this.paintHud();
  }
  paintHud() { this.hud.setText(`得分 ${this.score}   剩余 ${Math.ceil(this.remaining)} 秒`); }
  endGame() {
    if (this.finished) return;
    this.finished = true;
    this.remaining = 0;
    this.paintHud();
    this.add.rectangle(240, 300, 390, 140, 0x07131f, 0.95);
    const restart = this.add.text(240, 300, `本局 ${this.score} 分\n点击重新开始`, {
      fontSize: '28px', color: '#fff1b4', align: 'center', lineSpacing: 16,
    }).setOrigin(0.5).setInteractive({ useHandCursor: true });
    restart.once('pointerdown', () => this.scene.restart());
  }
  update(_time, delta) {
    if (this.finished) return;
    const dt = Math.min(delta / 1000, 0.05);
    this.remaining = Math.max(0, this.remaining - dt);
    if (this.remaining === 0) { this.endGame(); return; }
    const pointer = this.input.activePointer;
    if (pointer.isDown) this.player.x = pointer.x;
    else this.player.x += ((this.cursors.right.isDown ? 1 : 0) - (this.cursors.left.isDown ? 1 : 0)) * 360 * dt;
    this.player.x = Phaser.Math.Clamp(this.player.x, 45, 435);
    this.spawnLeft -= dt;
    if (this.spawnLeft <= 0) {
      this.coins.push(this.add.circle(Phaser.Math.Between(20, 460), -12, 12, 0xffd166));
      this.spawnLeft += 0.6;
    }
    for (let i = this.coins.length - 1; i >= 0; i--) {
      const coin = this.coins[i];
      coin.y += 230 * dt;
      const caught = Math.abs(coin.x - this.player.x) <= 57 && Math.abs(coin.y - this.player.y) <= 22;
      if (caught) this.score++;
      if (caught || coin.y > 665) { coin.destroy(); this.coins.splice(i, 1); }
    }
    this.paintHud();
  }
}
window.workshopGame = new Phaser.Game({
  type: Phaser.AUTO, parent: 'game', width: 480, height: 640,
  backgroundColor: '#102538', scene: CatchGame,
  scale: { mode: Phaser.Scale.FIT, autoCenter: Phaser.Scale.CENTER_BOTH },
});

import { _decorator, Component, Node, UITransform, Graphics, Color, Label } from 'cc';
const { ccclass } = _decorator;

@ccclass('TargetGame')
export class TargetGame extends Component {
  private score = 0;
  private remaining = 30;
  private spawnLeft = 0;
  private playing = false;
  private target: Node | null = null;
  private hud!: Label;
  private startButton!: Node;

  start() {
    this.node.getComponent(UITransform)!.setContentSize(640, 720);
    const background = this.node.addComponent(Graphics);
    background.fillColor = new Color(12, 27, 43);
    background.rect(-320, -360, 640, 720);
    background.fill();
    this.hud = this.makeLabel('点击圆点 · 30秒挑战', 0, 300, 26);
    this.startButton = new Node('StartButton');
    this.startButton.parent = this.node;
    this.startButton.layer = this.node.layer;
    this.startButton.addComponent(UITransform).setContentSize(240, 80);
    const g = this.startButton.addComponent(Graphics);
    g.fillColor = new Color(63, 116, 131);
    g.roundRect(-120, -40, 240, 80, 12); g.fill();
    const label = this.makeLabel('开始 / 再来一局', 0, 0, 24);
    label.node.parent = this.startButton;
    // 监听仅注册一次，重开时只清理状态。
    this.startButton.on(Node.EventType.TOUCH_END, this.restart, this);
  }
  private makeLabel(text: string, x: number, y: number, fontSize: number): Label {
    const n = new Node('Text'); n.parent = this.node; n.layer = this.node.layer; n.setPosition(x, y);
    n.addComponent(UITransform).setContentSize(600, 60);
    const label = n.addComponent(Label);
    label.string = text; label.fontSize = fontSize; label.lineHeight = fontSize + 8;
    label.color = new Color(226, 247, 241);
    return label;
  }
  restart() {
    this.clearTarget();
    this.score = 0; this.remaining = 30; this.spawnLeft = 0;
    this.playing = true; this.startButton.active = false;
    this.refreshHud();
  }
  private clearTarget() {
    if (!this.target) return;
    // destroy在帧末执行，先停用，避免一帧内再次命中。
    this.target.active = false; this.target.destroy(); this.target = null;
  }
  private spawnTarget() {
    this.clearTarget();
    const n = new Node('Target'); n.parent = this.node; n.layer = this.node.layer;
    n.setPosition(Math.random() * 500 - 250, Math.random() * 400 - 200);
    n.addComponent(UITransform).setContentSize(64, 64);
    const g = n.addComponent(Graphics);
    g.fillColor = new Color(109, 237, 197); g.circle(0, 0, 32); g.fill();
    this.target = n;
    n.on(Node.EventType.TOUCH_END, () => {
      if (!this.playing || this.target !== n) return;
      this.score++; this.clearTarget(); this.spawnLeft = 0.12;
      this.refreshHud();
    });
  }
  private refreshHud() {
    this.hud.string = `得分 ${this.score}  ·  剩余 ${Math.ceil(this.remaining)} 秒`;
  }
  update(deltaTime: number) {
    if (!this.playing) return;
    const dt = Math.min(deltaTime, 0.05);
    this.remaining = Math.max(0, this.remaining - dt);
    this.spawnLeft -= dt;
    if (this.remaining <= 0) {
      this.playing = false; this.clearTarget();
      this.hud.string = `时间到！本局 ${this.score} 分`;
      this.startButton.active = true;
      return;
    }
    if (this.spawnLeft <= 0) { this.spawnTarget(); this.spawnLeft = 1.2; }
    this.refreshHud();
  }
  onDestroy() {
    this.startButton?.off(Node.EventType.TOUCH_END, this.restart, this);
    this.clearTarget();
  }
}
